head.script:
scwin.screenId = "jlddst50100";

///////// 1. 변수 및 선언 영역 /////////

scwin.haltYn = "";


///////// 2. 초기화 영역 /////////

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_listStatCd", fn: function () { return String(String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.listStatCd !== "undefined" && scwin.listStatCd !== null ? scwin.listStatCd : ""))(dma_pageContext.get("listStatCd")))); } },
        { childId: "ipt_listStatCd2", fn: function () { return String(String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.listStatCd !== "undefined" && scwin.listStatCd !== null ? scwin.listStatCd : ""))(dma_pageContext.get("listStatCd")))); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = async function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        $("#searchForm").find("#formUpClassCd").val("00");
        await scwin.fnCorpInfoSearch();
        await scwin.fnMainDisclosureSearch();
        if (scwin.isExaService === "Y" && scwin.svrGubun.indexOf("dr") < 0 && scwin.listStatCd === "Y") {
            await scwin.fnPrincipalIndexSearch();
        }
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst50100.onpageload' }); }
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

