/**
 * @method
 * @name scwin.tx_fnCorpInfoSearch_ajaxsubmit
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fnCorpInfoSearch_ajaxsubmit = async function () {
    const sbmOptions = {
        id: "tx_fnCorpInfoSearch_ajaxsubmit",
        method: "post",
        action: "/disclosureSimpleSearch.do?method=corpInfoSearchResult",
        ref: "dma_fnCorpInfoSearchAjaxsubmitReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jlddst50100.tx_fnCorpInfoSearch_ajaxsubmit" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

