    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnMainDisclosureSearchCallBack
 * @author Inswave
 * @date 2026. 09. 29
 * @param data
 * @returns
 * @hidden N
*/
scwin.fnMainDisclosureSearchCallBack = function (data) {
    /* sdd-asis-lifecycle:begin fnMainDisclosureSearchCallBack — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $(".contents-list").empty().append(data);
    $("tr:odd").addClass("active");
    console.warn('[sdd] 미실현(재설계 분류 #128): fnLegendTooltip(' + "" + ')');
    /* sdd-asis-lifecycle:end */
};
